<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="form">
				<view class="form-row">
					<view class="row-center">
						<u-input border="none"  placeholder="输入发送内容"
							placeholderClass="placeholder28" 
							:placeholderStyle="placeholderStyle"
							type="text" 
							fontSize="28rpx" 
							clearable 
							v-model="content" />
					</view>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="send" :disabled="content == ''">发送</button>
			</view>
			<view class="items" v-if="lists.length>0">
				<view style="height: 20rpx;"></view>
				<view class="item" v-for="(item,index) in lists" :key="index" @click="connect(item)">
					<image src="@/static/lanya.png" class="item-img" mode="aspectFit" />
					<view class="right">
						<view class="right-tit">{{item.name}}</view>
						<view class="right-time">{{item.deviceId}}</view>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<button class="submit-btn" :disabled="!openBluetoothSuccess"
				@click="startBluetoothDevicesDiscovery">开始搜索</button>
		</block>
	</view>
</template>

<script>
	var _this;
	// ArrayBuffer转16进度字符串示例
	function ab2hex(buffer) {
		const hexArr = Array.prototype.map.call(
			new Uint8Array(buffer),
			function(bit) {
				return ('00' + bit.toString(16)).slice(-2)
			}
		)
		return hexArr.join('')
	}
	function stringToHex(str) {
	  let hex = '';
	  for (let i = 0; i < str.length; i++) {
	    hex += str.charCodeAt(i).toString(16);
	  }
	  return hex;
	}
	export default {
		data() {
			return {
				content:'',
				openBluetoothSuccess: true,
				placeholderStyle:"color:#959595;",
				serviceId:'',
				characteristicId:'',
				services:[],
				writes:[],
				notifys:[]
			}
		},
		onLoad(e) {
			_this = this;
			setTimeout(() => {
				_this.load = false
			}, 500)
		},
		onUnload() {
			uni.stopBluetoothDevicesDiscovery({
				success(res) {
					console.log(res)
				},
				fail(fail) {
					console.log('fail: ', fail);
				}
			})
		},
		onReady() {
			_this.getBluetoothAdapterState()
			uni.onBluetoothDeviceFound(function(res) {
				let device = res.devices[0]
				console.log(res.devices[0])
				if (device.advertisServiceUUIDs.length>0) {
					console.log('包含uuid',device.advertisServiceUUIDs)
				}
				// console.log(ab2hex(devices[0].advertisData))
				_this.lists.push(device)
			})
		},
		methods: {
			//发送
			send(){
				console.log(_this.services,_this.writes);
				let deviceId = '84:C2:E4:40:7E:E3'
				let serviceId = '9ECADC24-0EE5-A9E0-93F3-A3B50100406E'
				// let characteristicId = '00002A05-0000-1000-8000-00805F9B34FB'
				let characteristicId = '9ECADC24-0EE5-A9E0-93F3-A3B50200406E'
				console.log(_this.deviceId,_this.serviceId,_this.characteristicId);
				// 向蓝牙设备发送一个0x00的16进制数据
				const buffer = new ArrayBuffer(_this.content.length * 2)
				const dataView = new Uint8Array(buffer)
				// dataView.setUint8(0, 0)
				for (var i = 0; i < _this.content.length; i++) {
					dataView[i] = _this.content.charCodeAt(i)
				}
				uni.writeBLECharacteristicValue({
				  // 这里的 deviceId 需要在 getBluetoothDevices 或 onBluetoothDeviceFound 接口中获取
				  deviceId:deviceId,
				  // 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
				  serviceId:serviceId,
				  // 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
				  characteristicId:characteristicId,
				  // 这里的value是ArrayBuffer类型
				  value: buffer,
				  success(res) {
				    console.log('writeBLECharacteristicValue success', res.errMsg)
				  },
				  fail(fail) {
				  	console.log('writeBLECharacteristicValue fail: ',fail);
				  }
				})
			},
			//链接蓝牙
			connect(item){
				uni.createBLEConnection({
				// 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
				  deviceId:item.deviceId,
				  success(res) {
					  _this.$u.vuex('deviceId', item.deviceId)
					_this.stopBluetoothDevicesDiscovery()
					_this.getBLEDeviceServices(item)
					console.log(res,"蓝牙连接成功")
				  },fail(res) {
					console.log("蓝牙连接失败",res)
				  }
				})
			},
			// 停止搜寻蓝牙设备
			stopBluetoothDevicesDiscovery(){
			    uni.stopBluetoothDevicesDiscovery({
			        success: e => {
			            console.log('停止搜索蓝牙设备:' + e.errMsg);
			        },
			        fail: e => {
			            console.log('停止搜索蓝牙设备失败，错误码：' + e.errCode);
			        }
			    });
			},
			//获取蓝牙的所有服务
			//这个地方使用了setTimeout等待一秒种再去获取，直接获取我们可能出现获取不到的情况
			getBLEDeviceServices(item){
			    setTimeout(()=>{
			        uni.getBLEDeviceServices({
			          // 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
			          deviceId:item.deviceId,
			          success:(res)=>{
			            // console.log("成功",res)
			            console.log('device services:', res)
			            //这里会获取到好多个services  uuid  我们只存储我们需要用到的就行，这个uuid一般硬件厂家会给我们提供
			            res.services.forEach((item1)=>{
							_this.serviceId = item1.uuid
							_this.getBLEDeviceCharacteristics(item,item1.uuid)
			                // if(item.uuid.indexOf("AE00")!=-1){
			                //     this.serviceId = item.uuid;
			                //     //进入特征
			                //     this.getBLEDeviceCharacteristics()
			                // }
							// 这里获取回调，读取成功就的值就会在这个地方接收到！！！
							uni.onBLECharacteristicValueChange((res)=>{
								console.log("监听成功",res)
								//res.value是ArrayBuffer类型的，官方给了一个方法转16进制，我们再进行操作
								let shiliu = ab2hex(res.value)
								console.log('shiliu',shiliu);
							})
			            })
			          }
			        })
			    },1000)
			},
			//获取蓝牙特征
			getBLEDeviceCharacteristics(item,serviceId){
			    setTimeout(()=>{
			        uni.getBLEDeviceCharacteristics({
			          // 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
			          deviceId:item.deviceId,
			          // 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
			          serviceId:serviceId,
			          success:(res)=>{
			            console.log(res,'特征getBLEDeviceCharacteristics')
			            // this.characteristics = res.characteristics
			            // console.log(res.characteristics)
			            //循环所有的uuid
			            // for(let i=0;i<3;i++){
			            //  this.notifyBLECharacteristicValueChange(res.characteristics[i].uuid)
			            //  console.log(res.characteristics[i].uuid)
			            //  console.log(i,'i')
			            // }
			            res.characteristics.forEach((item1)=>{
							let {read,write,notify} = item1.properties
							if (notify) {
								_this.notifyBLECharacteristicValueChange(item,serviceId,item1.uuid)
							}
							if (write) {
								if (!_this.services.includes(serviceId)) {
									_this.services.push(serviceId)
								}
								if (!_this.writes.includes(item1.uuid)) {
									_this.writes.push(item1.uuid)
								}
								_this.writeBLECharacteristicValue(item,serviceId,item1.uuid)
							}
							console.log('item1: ',item1);
							// _this.characteristicId = item1.uuid
							// _this.notifyBLECharacteristicValueChange(item,serviceId,item1.uuid)
			                // if(item.uuid.indexOf("AE02") != -1){
			                //     console.log('characteristicId:', item1.uuid)
			                //     //利用传参的形势传给下面的notify，这里的uuid如果都需要用到，就不用做判断了，建议使用setTimeout进行间隔性的调用此方法
			                //     this.notifyBLECharacteristicValueChange(item1.uuid)
			                // }
			            })
			          },
			          fail:(res)=>{
			            console.log(res)
			          }
			        })
			    },1000)
			},
			// 启用 notify 功能
			notifyBLECharacteristicValueChange(item,serviceId,characteristicId){
			    uni.notifyBLECharacteristicValueChange({
			      state: true, // 启用 notify 功能
			      // 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
			      deviceId:item.deviceId,
			      // 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
			      serviceId:serviceId,
			      // 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
			      characteristicId:characteristicId,
			      success:(res)=> {
			        // console.log(this.characteristicId)
					console.log(characteristicId,'--notifyBLECharacteristicValueChange success--',res)
			      },
			      fail:(res)=> {
			        console.log('notifyBLECharacteristicValueChange fail--', res.errMsg,`--${characteristicId}`)
			      }
			    })
			},
			//向低功耗蓝牙设备特征值中写入二进制数据。注意：必须设备的特征值支持 write 才可以成功调用。
			writeBLECharacteristicValue(item,serviceId,characteristicId){
				let str = '666'
				// 向蓝牙设备发送一个0x00的16进制数据
				const buffer = new ArrayBuffer(str.length * 2)
				const dataView = new Uint8Array(buffer)
				// dataView.setUint8(0, 0)
				for (var i = 0; i < str.length; i++) {
					dataView[i] = str.charCodeAt(i)
				}
				uni.writeBLECharacteristicValue({
				  // 这里的 deviceId 需要在 getBluetoothDevices 或 onBluetoothDeviceFound 接口中获取
				  deviceId:item.deviceId,
				  // 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
				  serviceId:serviceId,
				  // 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
				  characteristicId:characteristicId,
				  // 这里的value是ArrayBuffer类型
				  value: buffer,
				  success(res) {
				    console.log('writeBLECharacteristicValue success', res.errMsg,`--${characteristicId}`)
				  },
				  fail(fail) {
				  	console.log('writeBLECharacteristicValue fail: ',fail,`--${characteristicId}`);
				  }
				})
			},
			getBluetoothAdapterState() {
				uni.getBluetoothAdapterState({
					success(res) {
						let adapterState = res.adapterState
						_this.openBluetoothSuccess = adapterState.available && adapterState.powered
						console.log(res,adapterState)
					},
					fail(fail) {
						_this.openBluetoothAdapter()
						console.log('fail: ', fail);
					}
				})
			},
			openBluetoothAdapter() {
				uni.openBluetoothAdapter({
					success(res) {
						_this.openBluetoothSuccess = true
						console.log(res)
					},
					fail(fail) {
						console.log('fail: ', fail);
					}
				})
			},
			//开始搜寻附近的蓝牙外围设备。此操作比较耗费系统资源，请在搜索并连接到设备后调用 uni.stopBluetoothDevicesDiscovery 方法停止搜索。
			startBluetoothDevicesDiscovery() {
				// 以微信硬件平台的蓝牙智能灯为例，主服务的 UUID 是 FEE7。传入这个参数，只搜索主服务 UUID 为 FEE7 的设备
				uni.startBluetoothDevicesDiscovery({
					//要搜索的蓝牙设备主 service 的 uuid 列表。某些蓝牙设备会广播自己的主 service 的 uuid。
					//如果设置此参数，则只搜索广播包有对应 uuid 的主服务的蓝牙设备。建议主要通过该参数过滤掉周边不需要处理的其他蓝牙设备。
					//9ECADC24-0EE5-A9E0-93F3-A3B50100406E
					//00001800-0000-1000-8000-00805F9B34FB
					//00001801-0000-1000-8000-00805F9B34FB
					// services: ['9ECADC24'],
					success(res) {
						console.log(res)
					},
					fail(fail) {
						console.log('fail: ', fail);
					}
				})
			},
		},
	}
</script>
<style lang="scss" scoped>
	@import "static/css/form.scss";
	.container {
		.items {
			padding: 0 30rpx;

			.item {
				padding: 20rpx 20rpx;
				@include flex-box();
				background: #fff;
				border-radius: 20rpx;
				margin-bottom: 20rpx;

				.item-img {
					flex-shrink: 0;
					width: 130rpx;
					height: 130rpx;
					margin-right: 20rpx;
					border-radius: 10rpx;
				}

				.right {
					width: calc(100% - 150rpx);
					@include flex-box(column, space-evenly);

					.right-tit {
						font-weight: 500;
						font-size: 30rpx;
						width: 100%;
						overflow: hidden;
						text-overflow: ellipsis;
						white-space: nowrap;
					}

					.right-time {
						color: $text-595959;
					}
				}
			}
		}
	}
</style>